DO $$
DECLARE
  missing integer;
BEGIN
  SELECT count(*) INTO missing
  FROM public.blog_posts
  WHERE status = 'published' AND branded_cta IS NULL;

  IF missing > 0 THEN
    RAISE NOTICE 'blog_posts: % published post(s) still have no branded CTA', missing;
  END IF;
END $$;
